 {
  "filename": "1993MAG-93-132[1].pdf",
  "title": "Transformor",
  "authors": "T.Ogawa and",
  "abstract_excerpt": "小川 . 達成、 斎藤   北古\nT.Ogawa and\nY.Saito\n法政大学\n工学部\nCollege\nof\nEngineering,\nHosei\nUnivorsity\n1 . まえかき\nパーソナルコンピュータやワードプロセッサー等で代表される小型電子機\n器のより小型 ・ 軽畳・ 高性能・ 高機能化の要求から、 麗源部の小型・ 軽量化\nが精力的に試みられている: 電源部の小型・軽貴化を指む大きな原因は変圧\n器やインダクタンス泰子等の磁気部品にある。 変圧器やインダクタンスを小\n型 ・ 軽量化するため、 もっぱら動作周波数の高周波化と高周波特性の良好な\n磁性材料を開発し 採用する方法が行われている。\nさて、 高周波動作においては、 表皮効果が導体中の電流だけでなく、 磁性\n体中の磁束に対しても無視できない。 この事実にも苅らず、 多くの高周波変\n圧器の構造は古典的な内鉄型か外鉄型である。 筆者等の磁気ヒステリシスを\n考高した数値解析によれば、 磁気ヒステリシスの大きな材料ほど磁束潰透深\nさは深くなり、 磁性体中の磁束は均一に分布するが、 磁気ヒステリシスに起\n因する損失も大きくなる[1‑3]。 このため、 多くの高周波変圧器においては一\n磁気ヒステリシスが小さく 透磁率の大きな材料が採用されている。 しかし̲\n低磁気ヒステリシスかつ高透磁率の材料になるほど表皮効果の影響が顕着に\n現れるため、 磁束は磁性材料中を均一に分布せず表面に巣中する。\nこのような亨実から、 筆者らは、 表皮効果を少なくして高効率の変圧器を\n実現するには、 樽造的に極めて複雑化することが予想され: ひいては生産コ\nストの面から実用化が極めて因難であると判断した。 むしろ表皮効果を積極\n的に利用し、 樽造が簡単で、 製造が容易な高周波変圧器の実現性が高いと考\nえ、 高周波空心変圧器を提案した [4].",
  "page_count": 10,
  "is_scanned": false,
  "relative_path": "00_電磁界解析\\90_各大学の研究内容\\斎藤研究室\\高周波トランス\\1993MAG-93-132[1].pdf"
 },
