 {
  "filename": "More Electric Engine 制御技術の実用化研究.pdf",
  "title": "IHI 技報　Vol.52  No.1 ( 2012 )",
  "authors": "IHI MEE の研究は，燃料システムの効率化を図るため",
  "abstract_excerpt": "1.　緒　　　　言\n航空産業界における航空機およびエンジンの効率向上は，\n地球温暖化防止に対する取組みとして重要になっている．\n電動化エンジンの促進 ( MEE：More Electric Engine ) は，\n航空機の電動化の促進 ( MEA：More Electric Aircraft ) の\n一環でシステム化されたエンジン抽気の廃止やフライトコ\nントロールの電動化に連携し，エンジンの軽量化や効率の\n改善を担う技術である．\nIHI MEE の研究は，燃料システムの効率化を図るため\nの制御システムを開発するとともに，高電圧の電動化技術\nによって機器の小型・軽量化を実現する．エンジン制御シ\nステムの電動化によって地球環境負荷低減や燃費改善が図\nられ，客先の要求である運航コストの低減にもこたえるこ\nとが可能になる．\n2.　MEE 開発概要\n2. 1　開発経緯\n本研究では燃料消費率の向上やCO2 削減のため，燃料\nシステム，電力システム，そのほかのエンジン制御システ\nム全体に焦点を当てた，MEE 制御技術の実用化に向け研\n究を進めている．すでに航空機メーカではMEA 実用化\nのために高電圧電源システムを導入し，電動のエンジン\nスタータと発電機を兼ねたスタータジェネレータ，電動\nアクチュエータ，電動ECS（環境制御装置：Environment \nControl System ）をBoeing787（アメリカ：ボーイング\n社）やAirbusA380（フランス：エアバス社）で実現して\nいる．\nMEA は電力へのエネルギーマネジメントの統合化と\nエンジン抽気レスに特長づけられ，① 燃料消費率の向上 \n② 定時出発率の改善 ③ 客室空気の清浄化による乗客満\n足度の向上 ④ 保守・点検の利便化，を提供している ( 1 )．\nMEE はMEA と連携し，エンジンの軽量化や効率の改善\nを担",
  "page_count": 10,
  "is_scanned": false,
  "relative_path": "00_電磁界解析\\99_アプリケーション\\モータ\\More Electric Engine 制御技術の実用化研究.pdf"
 },
