 {
  "filename": "多芯線と導体.pdf",
  "title": "船木和夫・住吉文夫 共善",
  "authors": "",
  "abstract_excerpt": "超伝導工学の基燕\n995,5,22\n多恋線と導体\n船木和夫住吉文夫 共着\n京研空所\n産業国書\n\n序\n文\n1980 年代の中頃から, 超伝導の世界では; 酸化物超伝導体の発見; 交流超伝\n導線の開発;超伝導装置の大型化などのニューウェーブが起きている. 第一の\nウェーブでは超伝導の応用を液体ヘリウム温度から液体峯素温度のレベルまで\n広げる可能性が; 第二のウェーブでは電力機器の超伝導化への足掛かりお; さ\nらに, 第三のウェープでは核融合実験装置をはじめとする2] 世紀に向けたエネ\nルギー革命への基盤技術の確立が;\nそれぞれ期待されている.しかし, 従来の\n金属系超伝導体の歴史をみると, 超伝導材料の発見が線材; 導体; 装置に展開\nしていきーつの超伝導応用技術にたどりつくまでに 10年を単位とする長い開発\n研究の期間を要している.これは; 超伝導装置が高い亀流密度や磁界を利用す\nる高機能型であることと表裏一体の結果ともいえる.\nこれら超伝導のニューウ\nエーブは; それぞれの段階で新しい応用への芽を提供しているが;\nこのような\n芽を育てていくには; 特に超伝導材料; 線材; 導体の各レベルでの特性評価と\n適用性の判断が重要になる.\n「超伝導工学の基磁」シリーナは; 超伝導応用の歴\n史の中で屈指のこの転換期に超伝導応用の基磁となる基本的な考え方を整理\nこれから超伝導関連分野の勉強を始めようとしている学生諸君;\nあるいはこの\n方面ですでに活曜されている方々の今後の活動を支援することを目的として\n画されている.\n本書は, 「磁束ピンニングと亀磁現象」 編; 「超伝導材料」 編と合わせてシ\n一ズ3部作を構成する.他の2編では超伝導体自体の基磁的物性や電磁現象, お\nよび超伝導薄膜・ 線材の製作法などが主題となっている. 本書では;\nいろいろ\nな超伝導装置に利用するときに問題となる",
  "page_count": 345,
  "is_scanned": false,
  "relative_path": "00_電磁界解析\\99_アプリケーション\\加速器\\00_教科書\\多芯線と導体.pdf"
 },
